{"function": "() => {
    const articles = [];
    const listItems = document.querySelectorAll('article li');
    let currentArticle = null;
    for (const li of listItems) {
        const text = li.textContent.trim();
        if (text.startsWith('ARTICLE')) {
            // Extract article title without following rule text
            const match = text.match(/^ARTICLE [A-Z]+\. [A-Z ]+/);
            const title = match ? match[0] : text;
            // Check if we already have this article (by title)
            if (!articles.find(a => a.title === title)) {
                currentArticle = { title, rules: [] };
                articles.push(currentArticle);
            }
        } else if (currentArticle) {
            const link = li.querySelector('a');
            if (link) {
                const ruleNum = link.textContent.trim();
                const title = li.textContent.replace(link.textContent, '').trim().replace(/^\.\s*/, '');
                currentArticle.rules.push({ rule: ruleNum, title });
            }
        }
    }
    // Now count titles containing 'witness' case-insensitive
    const counts = articles.map(article => {
        const count = article.rules.filter(rule => 
            rule.title.toLowerCase().includes('witness')).length;
        return { article: article.title, count, rules: article.rules };
    });
    return counts;
}"}

