{"function": "() => {
  const articles = [];
  // Find the main list containing articles
  const mainList = document.querySelector('main article ul');
  if (!mainList) return [];

  const listItems = mainList.children;
  for (let i = 0; i < listItems.length; i++) {
    const li = listItems[i];
    // Get the article name (text node that starts with ARTICLE)
    const articleTextNodes = Array.from(li.childNodes).filter(n => n.nodeType === Node.TEXT_NODE && n.textContent.trim().startsWith('ARTICLE'));
    if (articleTextNodes.length === 0) continue;

    const articleName = articleTextNodes[0].textContent.trim();

    // Find nested list of rules
    const ruleList = li.querySelector('ul');
    const rules = [];
    if (ruleList) {
      const ruleItems = ruleList.querySelectorAll('li');
      ruleItems.forEach(ruleLi => {
        // Get link and following text
        const link = ruleLi.querySelector('a');
        const textNodes = Array.from(ruleLi.childNodes).filter(n => n.nodeType === Node.TEXT_NODE && n.textContent.trim());
        let ruleTitle = '';
        if (link) {
          // Combine link text and following text
          ruleTitle = link.textContent + (textNodes[0] ? textNodes[0].textContent : '');
        } else {
          ruleTitle = ruleLi.textContent.trim();
        }
        rules.push(ruleTitle.trim());
      });
    }

    articles.push({
      article: articleName,
      rules: rules
    });
  }
  return articles;
}"}

