        if (el.textContent.includes('Committee Notes on Rules—2011 Amendment')) {
            target = el;
            break;
        }
    }
    if (!target) return null;
    // Get the next sibling element(s) that are paragraphs until next heading
    let result = target.textContent;
    let next = target.nextElementSibling;
    while (next && !next.textContent.includes('Committee Notes on Rules') && !next.textContent.includes('Notes of Advisory Committee')) {
        result += '\n' + next.textContent;
        next = next.nextElementSibling;
    }
    return result;
}');
